import type { Prisma, PrismaClient } from "@prisma/client";

/**
 * Batched writer. The engine pushes fully-formed rows here; the writer flushes via
 * createMany once a buffer threshold or time interval is hit, so we never hold the
 * whole crawl in memory. Page ids are generated by the engine (so Link/Asset rows
 * can reference them) — see engine.ts.
 */
export class CrawlWriter {
  private pages: Prisma.PageCreateManyInput[] = [];
  private links: Prisma.LinkCreateManyInput[] = [];
  private redirects: Prisma.RedirectCreateManyInput[] = [];
  private assets: Prisma.AssetCreateManyInput[] = [];

  constructor(
    private readonly prisma: PrismaClient,
    private readonly batchSize = 50,
  ) {}

  addPage(p: Prisma.PageCreateManyInput) {
    this.pages.push(p);
  }
  addLinks(l: Prisma.LinkCreateManyInput[]) {
    if (l.length) this.links.push(...l);
  }
  addRedirects(r: Prisma.RedirectCreateManyInput[]) {
    if (r.length) this.redirects.push(...r);
  }
  addAssets(a: Prisma.AssetCreateManyInput[]) {
    if (a.length) this.assets.push(...a);
  }

  get bufferedPages() {
    return this.pages.length;
  }

  shouldFlush() {
    return (
      this.pages.length >= this.batchSize ||
      this.links.length >= this.batchSize * 10 ||
      this.assets.length >= this.batchSize * 10
    );
  }

  async flush() {
    if (
      this.pages.length === 0 &&
      this.links.length === 0 &&
      this.redirects.length === 0 &&
      this.assets.length === 0
    ) {
      return;
    }
    const pages = this.pages;
    const links = this.links;
    const redirects = this.redirects;
    const assets = this.assets;
    this.pages = [];
    this.links = [];
    this.redirects = [];
    this.assets = [];

    // Pages first (Link/Asset FK depend on Page.id). skipDuplicates guards against
    // the rare race where the same normalised URL is admitted twice.
    await this.prisma.page.createMany({ data: pages, skipDuplicates: true });
    await Promise.all([
      links.length ? this.prisma.link.createMany({ data: links, skipDuplicates: true }) : null,
      redirects.length ? this.prisma.redirect.createMany({ data: redirects }) : null,
      assets.length ? this.prisma.asset.createMany({ data: assets, skipDuplicates: true }) : null,
    ]);
  }
}
